// MapServiceHandler is an implementation of the meurpg.maps.v1.MapService service.
type MapServiceHandler interface {
	// ListMaps lists the campaign's maps the caller may see, oldest first:
	// every map for the master, each with its state; for a player, only the
	// revealed maps and the session's current map. Any member may call it.
	// The list is not paginated: a campaign has at most 200 maps.
	//
	// Errors:
	//   - `not_found`: the campaign does not exist, or the caller is not a
	//     member of it.
	ListMaps(context.Context, *connect.Request[v1.ListMapsRequest]) (*connect.Response[v1.ListMapsResponse], error)
	// GetMap returns one map with its points and tokens, as the caller may
	// see them: the master gets every point and token, each with its state; a
	// player gets only the revealed points and the visible tokens. Any member
	// may call it. The app calls it again whenever the live session says the
	// map changed (`map_changed`, `current_map_changed`).
	//
	// Errors:
	//   - `not_found`: the map is not in this campaign, or the caller is a
	//     player and the map is hidden from them; the campaign does not
	//     exist, or the caller is not a member of it.
	GetMap(context.Context, *connect.Request[v1.GetMapRequest]) (*connect.Response[v1.GetMapResponse], error)
	// CreateMap creates a map from an image of the campaign's gallery. Only
	// the campaign's master may call it. The map starts hidden, without
	// points or tokens.
	//
	// Errors:
	//   - `invalid_argument`: the name breaks its rules, or image_id is not an
	//     image of the campaign's gallery (it may have been deleted in
	//     another tab).
	//   - `not_found`: the campaign does not exist, or the caller is not a
	//     member of it.
	//   - `permission_denied`: the caller is a player.
	//   - `resource_exhausted`: the campaign already has 200 maps.
	CreateMap(context.Context, *connect.Request[v1.CreateMapRequest]) (*connect.Response[v1.CreateMapResponse], error)
	// UpdateMap renames a map or changes its image. Only the campaign's
	// master may call it. The points and tokens keep their positions, which
	// are relative to the image's size.
	//
	// revision must be the revision the client last read. If the map's name
	// or image changed since, the call fails with `aborted` and changes
	// nothing: the app reloads the map and the master tries again. On
	// success, the revision goes up by one.
	//
	// Errors:
	//   - `invalid_argument`: nothing to change, revision less than 1, the
	//     name breaks its rules, or image_id is not an image of the
	//     campaign's gallery.
	//   - `not_found`: the map is not in this campaign, the campaign does not
	//     exist, or the caller is not a member of it.
	//   - `permission_denied`: the caller is a player.
	//   - `aborted`: revision is stale.
	UpdateMap(context.Context, *connect.Request[v1.UpdateMapRequest]) (*connect.Response[v1.UpdateMapResponse], error)
	// DeleteMap deletes a map with its points and tokens. Only the campaign's
	// master may call it. It cannot be undone. The gallery image stays.
	// Submap points of other maps that led to it lose their target, and if
	// it was the session's current map, the session has no current map
	// anymore (`current_map_changed` with an empty map_id).
	//
	// Errors:
	//   - `not_found`: the map is not in this campaign (or was already
	//     deleted), the campaign does not exist, or the caller is not a member
	//     of it.
	//   - `permission_denied`: the caller is a player.
	DeleteMap(context.Context, *connect.Request[v1.DeleteMapRequest]) (*connect.Response[v1.DeleteMapResponse], error)
	// SetMapRevealed shows a map to the players, or hides it again (RN-10).
	// Only the campaign's master may call it. Revealing a revealed map, or
	// hiding a hidden one, changes nothing. Hiding the session's current map
	// does not take it away from the players while it stays current.
	//
	// Errors:
	//   - `not_found`: the map is not in this campaign, the campaign does not
	//     exist, or the caller is not a member of it.
	//   - `permission_denied`: the caller is a player.
	SetMapRevealed(context.Context, *connect.Request[v1.SetMapRevealedRequest]) (*connect.Response[v1.SetMapRevealedResponse], error)
	// SetMapGrid sets the battle grid of a map, or clears it (MR-013, RN-21).
	// Only the campaign's master may call it. The grid is made of squares of
	// 1.5 m (5 ft): columns says how many fit across the image's width, and
	// the rows follow the image's proportions. A combat can only start on a
	// map with a grid (PlayService/CombatService.StartEncounter).
	//
	// A combat already running keeps the grid it started with. A player who
	// sees the map gets `map_changed`.
	//
	// Errors:
	//   - `invalid_argument`: columns is neither 0 nor between 4 and 200.
	//   - `not_found`: the map is not in this campaign, the campaign does not
	//     exist, or the caller is not a member of it.
	//   - `permission_denied`: the caller is a player.
	SetMapGrid(context.Context, *connect.Request[v1.SetMapGridRequest]) (*connect.Response[v1.SetMapGridResponse], error)
	// CreateMapPoint puts a point of interest on a map (MR-008). Only the
	// campaign's master may call it. The point starts hidden.
	//
	// Errors:
	//   - `invalid_argument`: a field breaks its rules; kind is unspecified;
	//     target_map_id is set on a point that is neither a SUBMAP nor a
	//     BATTLE, is the point's own map, or is not a map of the campaign.
	//   - `not_found`: the map is not in this campaign, the campaign does not
	//     exist, or the caller is not a member of it.
	//   - `permission_denied`: the caller is a player.
	//   - `resource_exhausted`: the map already has 200 points.
	CreateMapPoint(context.Context, *connect.Request[v1.CreateMapPointRequest]) (*connect.Response[v1.CreateMapPointResponse], error)
	// UpdateMapPoint changes a point: each field set in the request replaces
	// the current value, and unset fields stay as they are. Moving a point is
	// an update of x_bp and y_bp. Only the campaign's master may call it.
	// Changing the kind to anything but SUBMAP or BATTLE removes the target,
	// and changing it from SCENE removes the point's scene actions, clues, hooks
	// and "Mostrar a CD" switch (show_dc). Turning show_dc on or off while the
	// point is the open scene sends `scene_changed` to every stream.
	//
	// Errors:
	//   - `invalid_argument`: nothing to change; a field breaks its rules;
	//     target_map_id is set on a point that is neither a SUBMAP nor a
	//     BATTLE (after the change), is the point's own map, or is not a map
	//     of the campaign.
	//   - `not_found`: the point is not on this map, the map is not in this
	//     campaign, the campaign does not exist, or the caller is not a
	//     member of it.
	//   - `permission_denied`: the caller is a player.
	UpdateMapPoint(context.Context, *connect.Request[v1.UpdateMapPointRequest]) (*connect.Response[v1.UpdateMapPointResponse], error)
	// DeleteMapPoint deletes a point. Only the campaign's master may call it.
	// It cannot be undone.
	//
	// Errors:
	//   - `not_found`: the point is not on this map (or was already deleted),
	//     the map is not in this campaign, the campaign does not exist, or
	//     the caller is not a member of it.
	//   - `permission_denied`: the caller is a player.
	DeleteMapPoint(context.Context, *connect.Request[v1.DeleteMapPointRequest]) (*connect.Response[v1.DeleteMapPointResponse], error)
	// SetMapPointRevealed shows a point to the players, or hides it again
	// (RN-10, MR-009). Only the campaign's master may call it. The players see
	// it only on a map they see. Revealing a SCENE point also makes the scene
	// "discovered" (MR-030): the group may tag notes with it from then on, even
	// if the point is hidden again later.
	//
	// Errors:
	//   - `not_found`: the point is not on this map, the map is not in this
	//     campaign, the campaign does not exist, or the caller is not a
	//     member of it.
	//   - `permission_denied`: the caller is a player.
	SetMapPointRevealed(context.Context, *connect.Request[v1.SetMapPointRevealedRequest]) (*connect.Response[v1.SetMapPointRevealedResponse], error)
	// AddSceneAction puts one more check on a SCENE point (MR-015): a skill
	// check, an ability check or a saving throw, with an optional name and an
	// optional DC and how many attempts each player has (max_attempts, 1 by
	// default). Actions save one by one, as the master edits them: there is
	// no "save all". Only the campaign's master may call it. The action goes
	// last. When the point is the scene open in the session, the streams get
	// `scene_changed`.
	//
	// Errors:
	//   - `invalid_argument`: the point is not a SCENE point; key is not a
	//     skill, an ability check or a saving throw of the rules ("skill:
	//     investigation", "ability:str", "save:wis": never an attack, a spell
	//     or a feature); name is longer than 60 characters; dc is not 1 to
	//     30; max_attempts is not 0 to 5.
	//   - `not_found`: the point is not on this map, the map is not in this
	//     campaign, the campaign does not exist, or the caller is not a
	//     member of it.
	//   - `permission_denied`: the caller is a player.
	//   - `resource_exhausted`: the point already has 20 actions.
	AddSceneAction(context.Context, *connect.Request[v1.AddSceneActionRequest]) (*connect.Response[v1.AddSceneActionResponse], error)
	// UpdateSceneAction changes one action of a SCENE point: each field set
	// in the request replaces the current value. Only the campaign's master
	// may call it.
	//
	// Errors:
	//   - `invalid_argument`: nothing to change; a field breaks the rules
	//     AddSceneAction lists.
	//   - `not_found`: the action is not on this point, the point is not on
	//     this map, the map is not in this campaign, the campaign does not
	//     exist, or the caller is not a member of it.
	//   - `permission_denied`: the caller is a player.
	UpdateSceneAction(context.Context, *connect.Request[v1.UpdateSceneActionRequest]) (*connect.Response[v1.UpdateSceneActionResponse], error)
	// MoveSceneAction moves one action a place up or down in its point's
	// list. Moving the first one up, or the last one down, changes nothing.
	// Only the campaign's master may call it.
	//
	// Errors:
	//   - `invalid_argument`: direction is unspecified.
	//   - `not_found`: as UpdateSceneAction.
	//   - `permission_denied`: the caller is a player.
	MoveSceneAction(context.Context, *connect.Request[v1.MoveSceneActionRequest]) (*connect.Response[v1.MoveSceneActionResponse], error)
	// RemoveSceneAction takes one action off a SCENE point, with no
	// confirmation: the rolls already made stay in the session's history.
	// Only the campaign's master may call it.
	//
	// Errors:
	//   - `not_found`: as UpdateSceneAction.
	//   - `permission_denied`: the caller is a player.
	RemoveSceneAction(context.Context, *connect.Request[v1.RemoveSceneActionRequest]) (*connect.Response[v1.RemoveSceneActionResponse], error)
	// AddSceneClue puts one more clue on a SCENE point (MR-029): a short text
	// the master prepared, to reveal to players during the session
	// (RevealSceneClue). Clues save one by one, like the actions. Only the
	// campaign's master may call it. The clue goes last. A player never
	// receives a clue that was not revealed to them (RN-20). The streams of the
	// master get `map_changed` and, when the point is the open scene,
	// `scene_changed`; the players' streams get nothing.
	//
	// Errors:
	//   - `invalid_argument`: the point is not a SCENE point; text is empty or
	//     longer than 500 characters.
	//   - `not_found`: the point is not on this map, the map is not in this
	//     campaign, the campaign does not exist, or the caller is not a
	//     member of it.
	//   - `permission_denied`: the caller is a player.
	//   - `resource_exhausted`: the point already has 30 clues.
	AddSceneClue(context.Context, *connect.Request[v1.AddSceneClueRequest]) (*connect.Response[v1.AddSceneClueResponse], error)
	// UpdateSceneClue changes the text of one clue of a SCENE point. What
	// players already received keeps the text they were given. Only the
	// campaign's master may call it.
	//
	// Errors:
	//   - `invalid_argument`: text is empty or longer than 500 characters.
	//   - `not_found`: the clue is not on this point, the point is not on this
	//     map, the map is not in this campaign, the campaign does not exist,
	//     or the caller is not a member of it.
	//   - `permission_denied`: the caller is a player.
	UpdateSceneClue(context.Context, *connect.Request[v1.UpdateSceneClueRequest]) (*connect.Response[v1.UpdateSceneClueResponse], error)
	// MoveSceneClue moves one clue a place up or down in its point's list.
	// Moving the first one up, or the last one down, changes nothing. Only the
	// campaign's master may call it.
	//
	// Errors:
	//   - `invalid_argument`: direction is unspecified.
	//   - `not_found`: as UpdateSceneClue.
	//   - `permission_denied`: the caller is a player.
	MoveSceneClue(context.Context, *connect.Request[v1.MoveSceneClueRequest]) (*connect.Response[v1.MoveSceneClueResponse], error)
	// RemoveSceneClue takes one clue off a SCENE point, with no confirmation:
	// the players who already received it keep it in their notes, with the
	// text they were given. Only the campaign's master may call it.
	//
	// Errors:
	//   - `not_found`: as UpdateSceneClue.
	//   - `permission_denied`: the caller is a player.
	RemoveSceneClue(context.Context, *connect.Request[v1.RemoveSceneClueRequest]) (*connect.Response[v1.RemoveSceneClueResponse], error)
	// RevealSceneClue gives a clue to the players the master chose (MR-029,
	// question 59: the app sends every player character checked by default).
	// Each one gets it once: revealing again to a player who has it changes
	// nothing, and there is no way to take it back. The clue lands in the
	// player's notes (meurpg.notes.v1.NotesService.ListNotes) as "Pista do
	// mestre", tagged with the scene once the group has discovered it, whether
	// or not they are online. Only the campaign's master may call it, with or
	// without an open session.
	//
	// While a session is open, a `clue_revealed` event goes into its history
	// (IDs only, never the text), the streams of the players who got it now
	// receive `notes_changed`, and the master's, `scene_changed` when the
	// point is the open scene. No other player's stream hears of it.
	//
	// Errors:
	//   - `invalid_argument`: character_ids is empty or has more than 50.
	//   - `not_found`: the clue is not in this campaign, or one of the
	//     characters is not a living player character of it, or has no
	//     player, or the campaign does not exist, or the caller is not a
	//     member of it.
	//   - `permission_denied`: the caller is a player.
	RevealSceneClue(context.Context, *connect.Request[v1.RevealSceneClueRequest]) (*connect.Response[v1.RevealSceneClueResponse], error)
	// PlaceMapToken puts a character's token on a map, or moves it there if
	// it is already on the map (MR-012). Only the campaign's master may call
	// it. The character must be a living character of the campaign: a
	// player's (not dead, not waiting for approval) or an NPC. A new token of
	// a player's character starts visible; a new NPC token starts hidden
	// (question 31 for Samuel). Moving keeps the token's state.
	//
	// During a session, a move reaches the watching members as `token_moved`:
	// everyone when the token is visible on a map the players see, only the
	// master otherwise. A new token reaches them as `map_changed`.
	//
	// Errors:
	//   - `not_found`: the character is not a living character of the
	//     campaign, the map is not in this campaign, the campaign does not
	//     exist, or the caller is not a member of it.
	//   - `permission_denied`: the caller is a player.
	PlaceMapToken(context.Context, *connect.Request[v1.PlaceMapTokenRequest]) (*connect.Response[v1.PlaceMapTokenResponse], error)
	// SetMapTokenHidden hides a token from the players, or shows it again
	// (RN-10). Only the campaign's master may call it.
	//
	// Errors:
	//   - `not_found`: the character has no token on this map, the map is not
	//     in this campaign, the campaign does not exist, or the caller is not
	//     a member of it.
	//   - `permission_denied`: the caller is a player.
	SetMapTokenHidden(context.Context, *connect.Request[v1.SetMapTokenHiddenRequest]) (*connect.Response[v1.SetMapTokenHiddenResponse], error)
	// RemoveMapToken takes a character's token off a map. Only the
	// campaign's master may call it.
	//
	// Errors:
	//   - `not_found`: the character has no token on this map, the map is not
	//     in this campaign, the campaign does not exist, or the caller is not
	//     a member of it.
	//   - `permission_denied`: the caller is a player.
	RemoveMapToken(context.Context, *connect.Request[v1.RemoveMapTokenRequest]) (*connect.Response[v1.RemoveMapTokenResponse], error)
}

